import type { DiffFile } from "./types";

/** Changed lines past which a file starts collapsed. */
export const AUTO_COLLAPSE_LINES = 1000;

/**
 * Files a tool writes, by name: nobody reviews a lockfile line by line, and
 * one can be tens of thousands of lines.
 */
const GENERATED_NAMES = new Set([
  "pnpm-lock.yaml",
  "package-lock.json",
  "npm-shrinkwrap.json",
  "yarn.lock",
  "bun.lock",
  "Cargo.lock",
  "Gemfile.lock",
  "poetry.lock",
  "uv.lock",
  "Pipfile.lock",
  "composer.lock",
  "go.sum",
  "flake.lock",
  "Podfile.lock",
  "pubspec.lock",
  "mix.lock",
]);

/** Generated by extension: minified bundles and source maps. */
const GENERATED_SUFFIXES = [".min.js", ".min.css", ".map"];

/** Why a file starts collapsed, or `null` when it starts open. */
export type AutoCollapseReason = "generated" | "large";

export function autoCollapseReason(file: DiffFile): AutoCollapseReason | null {
  const name = file.path.slice(file.path.lastIndexOf("/") + 1);
  if (
    GENERATED_NAMES.has(name) ||
    GENERATED_SUFFIXES.some((suffix) => name.endsWith(suffix))
  )
    return "generated";
  if (file.added + file.removed > AUTO_COLLAPSE_LINES) return "large";
  return null;
}

/**
 * Which files are collapsed: the user's own choice for a file where they made
 * one, and otherwise the default the file got when it was first seen. Both
 * hold as the diff refreshes, so a file someone expanded stays expanded while
 * an agent keeps editing it, and a file that crosses the size line while
 * being read does not snap shut under the reader.
 *
 * `defaults` remembers each path's default the first time it appears and is
 * filled in here; the caller keeps it for as long as the pane is open.
 */
export function collapsedFiles(
  files: DiffFile[],
  choices: ReadonlyMap<string, boolean>,
  defaults: Map<string, boolean>,
): Set<string> {
  const collapsed = new Set<string>();
  for (const file of files) {
    let byDefault = defaults.get(file.path);
    if (byDefault === undefined) {
      byDefault = autoCollapseReason(file) !== null;
      defaults.set(file.path, byDefault);
    }
    if (choices.get(file.path) ?? byDefault) collapsed.add(file.path);
  }
  return collapsed;
}
